    ("Inherited from %@", ("Heredados de %@", "Ereditati da %@", "Hérités de %@", "Geerbt von %@", "Унаследованы от «%@»", "موروثة من %@", "%@ से विरासत में मिले", "Örökölve innen: %@", "Zděděno z %@", "Odziedziczone z %@")),
