    # Share import: a shared picture or file becomes an image or file note, or goes into a text note
    ("Image Note", ("Nota de imagen", "Nota immagine", "Note image", "Bildnotiz", "Заметка-изображение", "ملاحظة صورة", "इमेज नोट", "Képjegyzet", "Obrázková poznámka", "Notatka z obrazem")),
    ("File Note", ("Nota de archivo", "Nota file", "Note fichier", "Dateinotiz", "Заметка-файл", "ملاحظة ملف", "फ़ाइल नोट", "Fájljegyzet", "Souborová poznámka", "Notatka z plikiem")),
    ("Text Note", ("Nota de texto", "Nota di testo", "Note de texte", "Textnotiz", "Текстовая заметка", "ملاحظة نصية", "टेक्स्ट नोट", "Szöveges jegyzet", "Textová poznámka", "Notatka tekstowa")),
    ("The picture becomes the note itself, like an image note in Trilium.", ("La imagen se convierte en la propia nota, como una nota de imagen en Trilium.", "L’immagine diventa la nota stessa, come una nota immagine in Trilium.", "L’image devient la note elle-même, comme une note image dans Trilium.", "Das Bild wird selbst zur Notiz, wie eine Bildnotiz in Trilium.", "Изображение само становится заметкой, как заметка-изображение в Trilium.", "تصبح الصورة هي الملاحظة نفسها، مثل ملاحظة الصورة في Trilium.", "चित्र ही नोट बन जाता है, जैसे Trilium में इमेज नोट।", "A kép maga lesz a jegyzet, mint egy képjegyzet a Triliumban.", "Obrázek se stane samotnou poznámkou, jako obrázková poznámka v Trilium.", "Obraz staje się samą notatką, jak notatka z obrazem w Trilium.")),
    ("The picture goes into a new text note, where you can write around it.", ("La imagen va en una nueva nota de texto, donde puedes escribir alrededor.", "L’immagine va in una nuova nota di testo, dove puoi scriverci intorno.", "L’image est placée dans une nouvelle note de texte, où vous pouvez écrire autour.", "Das Bild kommt in eine neue Textnotiz, in der du drumherum schreiben kannst.", "Изображение помещается в новую текстовую заметку, где вокруг него можно писать.", "توضع الصورة في ملاحظة نصية جديدة، حيث يمكنك الكتابة حولها.", "चित्र एक नए टेक्स्ट नोट में जाता है, जहाँ आप उसके आसपास लिख सकते हैं।", "A kép egy új szöveges jegyzetbe kerül, ahol köré írhatsz.", "Obrázek se vloží do nové textové poznámky, kde kolem něj můžete psát.", "Obraz trafia do nowej notatki tekstowej, w której możesz pisać wokół niego.")),
    ("The file becomes the note itself, like a file note in Trilium.", ("El archivo se convierte en la propia nota, como una nota de archivo en Trilium.", "Il file diventa la nota stessa, come una nota file in Trilium.", "Le fichier devient la note elle-même, comme une note fichier dans Trilium.", "Die Datei wird selbst zur Notiz, wie eine Dateinotiz in Trilium.", "Файл сам становится заметкой, как заметка-файл в Trilium.", "يصبح الملف هو الملاحظة نفسها، مثل ملاحظة الملف في Trilium.", "फ़ाइल ही नोट बन जाती है, जैसे Trilium में फ़ाइल नोट।", "A fájl maga lesz a jegyzet, mint egy fájljegyzet a Triliumban.", "Soubor se stane samotnou poznámkou, jako souborová poznámka v Trilium.", "Plik staje się samą notatką, jak notatka z plikiem w Trilium.")),
    ("The file is attached to a new text note, where you can write around it.", ("El archivo se adjunta a una nueva nota de texto, donde puedes escribir alrededor.", "Il file viene allegato a una nuova nota di testo, dove puoi scriverci intorno.", "Le fichier est joint à une nouvelle note de texte, où vous pouvez écrire autour.", "Die Datei wird an eine neue Textnotiz angehängt, in der du drumherum schreiben kannst.", "Файл прикрепляется к новой текстовой заметке, где вокруг него можно писать.", "يُرفق الملف بملاحظة نصية جديدة، حيث يمكنك الكتابة حوله.", "फ़ाइल एक नए टेक्स्ट नोट में संलग्न की जाती है, जहाँ आप उसके आसपास लिख सकते हैं।", "A fájl egy új szöveges jegyzethez csatolódik, ahol köré írhatsz.", "Soubor se připojí k nové textové poznámce, kde kolem něj můžete psát.", "Plik zostaje dołączony do nowej notatki tekstowej, w której możesz pisać wokół niego.")),
    ("Attaching the file needs a connection.", ("Adjuntar el archivo requiere conexión.", "Per allegare il file serve una connessione.", "Joindre le fichier nécessite une connexion.", "Zum Anhängen der Datei ist eine Verbindung nötig.", "Чтобы прикрепить файл, нужно подключение.", "يتطلب إرفاق الملف اتصالًا.", "फ़ाइल संलग्न करने के लिए कनेक्शन चाहिए।", "A fájl csatolásához kapcsolat szükséges.", "K připojení souboru musíte být online.", "Dołączenie pliku wymaga połączenia.")),
    ('Navigation Tabs', ('Pestañas de navegación', 'Schede di navigazione', 'Onglets de navigation', 'Navigationstabs', 'Вкладки навигации', 'علامات تبويب التنقل', 'नेविगेशन टैब', 'Navigációs fülek', 'Navigační karty', 'Karty nawigacji')),
